INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427255, 16281, 'The Guardian', 'en', 'Russia ‘losing 6,000 more troops in Ukraine each month than it can recruit’', 'https://www.theguardian.com/world/2026/aug/28/russia-losing-6000-more-troops-than-it-can-recruit-each-month-in-ukraine-says-west', 'Moscow recruits an estimated 1,000 people a day but western officials say it cannot keep up with casualty level Russia is losing about 6,000 more troops in Ukraine each month than it can recruit, western officials have said. While Russia is still acquiring new battlefield recruits at speed, with an estimated rate of 1,000 a day, in the last two months even this has not been sufficient to replace those killed or injured. Continue reading...', 'https://i.guim.co.uk/img/media/52fa0198715e1df5b2ae80a8610f907294d1ccc8/456_0_4560_3648/master/4560.jpg?width=140&quality=85&auto=format&fit=max&s=5c438e3cd21166a27ac94c5258697a1d', '2026-08-28T17:05:02+00:00', '2026-08-29T00:03:19.828118'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
